#!/usr/bin/env node
// Mirror Claude Code subagents from .claude/agents/*.md into other tools' native agent files.
//
//   node scripts/sync-agents.mjs [--dir <project>] --targets codex,gemini,opencode,copilot
//                                [--model-map fast=X,standard=Y,deep=Z] [--check] [--dry-run]
//
// .claude/agents is the single source. Every generated file carries a marker, so a re-run can
// update it, and a hand-written file at the same path is never touched.
// Exit codes: 0 ok, 1 conflict or (with --check) pending changes, 2 usage error.
// Zero dependencies. Formats: research/agent-formats.md (sections 3 to 5, 7). Copilot CLI and
// VS Code also read .claude/agents directly, so the copilot target is optional.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const AGENTS_DIR = '.claude/agents';
const TAIL = 'edit the source and re-run sync-agents';
const MD_MARKER_RE = /^<!-- generated by claude-setup from .+; edit the source and re-run sync-agents -->$/m;
const TOML_MARKER_RE = /^# generated by claude-setup from .+; edit the source and re-run sync-agents$/m;
const note = (rel) => `generated by claude-setup from ${AGENTS_DIR}/${rel}; ${TAIL}`;

const USAGE = `usage: node sync-agents.mjs [--dir <project>] --targets <list> [--model-map fast=X,standard=Y,deep=Z] [--check] [--dry-run]
targets: codex, gemini, opencode, copilot (comma separated)
  --model-map tier=model pairs; tiers come from the Claude model (haiku=fast, sonnet=standard,
              opus/fable=deep; inherit or absent = none). Without a map no model is written.
              opencode needs provider/model-id values.
  --check     write nothing; exit 1 if any target would change
  --dry-run   print planned actions, write nothing
`;

// ---------------------------------------------------------------------------
// Parsing: the YAML frontmatter subset Claude agents use
// ---------------------------------------------------------------------------

function unquote(s) {
  const t = s.trim();
  if (t.length >= 2 && t[0] === t[t.length - 1]) {
    if (t[0] === '"') {
      try {
        return JSON.parse(t);
      } catch {
        return t.slice(1, -1);
      }
    }
    if (t[0] === "'") return t.slice(1, -1).replace(/''/g, "'");
  }
  return t;
}

// Split on commas outside quotes, brackets, braces and parens ("Bash(a, b)" stays whole).
function splitTop(s) {
  const parts = [];
  let depth = 0;
  let quote = null;
  let start = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (quote) {
      if (c === quote) quote = null;
    } else if (c === '"' || c === "'") quote = c;
    else if ('{[('.includes(c)) depth++;
    else if ('}])'.includes(c)) depth--;
    else if (c === ',' && depth === 0) {
      parts.push(s.slice(start, i));
      start = i + 1;
    }
  }
  parts.push(s.slice(start));
  return parts.map((p) => p.trim()).filter(Boolean);
}

function stripComment(s) {
  let quote = null;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (quote) {
      if (c === quote) quote = null;
    } else if (c === '"' || c === "'") quote = c;
    else if (c === '#' && (i === 0 || /\s/.test(s[i - 1]))) return s.slice(0, i);
  }
  return s;
}

// Block scalar (`>` folded, `|` literal) from its indented lines.
function blockScalar(style, lines) {
  const indent = Math.min(...lines.filter((l) => l.trim()).map((l) => l.match(/^\s*/)[0].length), Infinity);
  const cut = lines.map((l) => (l.trim() ? l.slice(indent === Infinity ? 0 : indent) : ''));
  if (style === '|') return cut.join('\n').trim();
  return cut.join('\n').split(/\n{2,}/).map((p) => p.split('\n').join(' ').trim()).join('\n').trim();
}

// -> { key: string | string[] | null }. null marks a nested map (hooks, mcpServers), unused here.
export function parseFrontmatter(lines) {
  const fm = {};
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/^([A-Za-z_][\w-]*)[ \t]*:(?:[ \t]+(.*)|[ \t]*)$/);
    if (!m) continue;
    const rest = (m[2] || '').trim();
    const head = stripComment(rest).trim();
    const block = [];
    let j = i + 1;
    while (j < lines.length && (!lines[j].trim() || /^\s/.test(lines[j]) || (!head && /^-(\s|$)/.test(lines[j])))) {
      block.push(lines[j++]);
    }
    i = j - 1;
    const body = block.filter((l) => l.trim());
    if (/^[>|][+-]?\d*$/.test(head)) fm[m[1]] = blockScalar(head[0], block);
    else if (!head) {
      if (!body.length) fm[m[1]] = '';
      else if (body.every((l) => /^\s*-(\s|$)/.test(l))) {
        fm[m[1]] = body.map((l) => unquote(stripComment(l.replace(/^\s*-\s*/, '')).trim())).filter(Boolean);
      } else fm[m[1]] = null;
    } else if (head.startsWith('[') && head.includes(']')) {
      fm[m[1]] = splitTop(head.slice(1, head.lastIndexOf(']'))).map(unquote).filter(Boolean);
    } else {
      const joined = [head, ...body.map((l) => l.trim())].join(' ');
      fm[m[1]] = unquote(body.length ? joined : head);
    }
  }
  return fm;
}

const asList = (v) => (Array.isArray(v) ? v : typeof v === 'string' ? splitTop(v).map(unquote) : []).filter(Boolean);
const toolBase = (t) => t.replace(/\(.*$/, '').trim();

// Claude model alias (or full id) -> cost tier used by --model-map.
export function tierOf(model) {
  const m = String(model || '').toLowerCase();
  if (m.includes('haiku')) return 'fast';
  if (m.includes('sonnet')) return 'standard';
  if (m.includes('opus') || m.includes('fable')) return 'deep';
  return null;
}

// -> { name, description, tools: string[] | null, disallowed, model, effort, body }
export function parseAgent(raw, stem) {
  const text = raw.replace(/^﻿/, '').replace(/\r\n/g, '\n');
  const m = text.match(/^---[ \t]*\n([\s\S]*?\n)?(?:---|\.\.\.)[ \t]*(?:\n|$)/);
  const fm = m ? parseFrontmatter((m[1] || '').split('\n')) : {};
  const body = (m ? text.slice(m[0].length) : text).replace(/^\n+/, '');
  const str = (v) => (typeof v === 'string' ? v.trim() : '');
  return {
    name: str(fm.name) || stem,
    description: str(fm.description).replace(/\s+/g, ' '),
    tools: fm.tools === undefined || fm.tools === null ? null : asList(fm.tools).map(toolBase),
    disallowed: asList(fm.disallowedTools).map(toolBase),
    model: str(fm.model),
    effort: str(fm.effort),
    body: body.replace(/\s+$/, '') + (body.trim() ? '\n' : ''),
  };
}

// ---------------------------------------------------------------------------
// Rendering, one function per target. Returns the file text, or null to skip.
// ctx: { rel, mapped (model-map value for the agent's tier or undefined), warn(msg) }
// ---------------------------------------------------------------------------

const yamlStr = (s) => (/^[A-Za-z_][\w./-]*$/.test(s) && !/^(true|false|null|yes|no|on|off|y|n)$/i.test(s) ? s : JSON.stringify(s));
const mdFile = (lines, a, rel) => `---\n${lines.join('\n')}\n---\n<!-- ${note(rel)} -->\n\n${instructionsOf(a)}`;

const EDIT_TOOLS = ['Edit', 'Write', 'MultiEdit', 'NotebookEdit'];

// Exact phrases in Claude-written bodies that read wrong in other tools. Applied to the body of
// generated files only; the source is never changed. Add pairs here. Matching needs a word
// boundary after the phrase, so "the Read tool" does not match "the Read tools".
const REWRITES = [
  ['You have no Bash', 'Do not run shell commands'],
  ['Use the Read tool to', 'Read files to'],
  ['Use the Grep tool to', 'Search the code to'],
  ['Use the Glob tool to', 'Find files to'],
  ['the Grep tool', 'search'],
  ['the Glob tool', 'file search'],
  ['the Read tool', 'reading files'],
  ['the Agent tool', 'subagents'],
];
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

export function rewriteBody(body) {
  return REWRITES.reduce((text, [from, to]) => text.replace(new RegExp(`${escapeRe(from)}(?!\\w)`, 'g'), to), body);
}

// One plain line stating what the source's `tools` allow. Codex role files have no sandbox
// field, so this line is the only place the read-only guarantee can live there. Tools listed in
// disallowedTools do not count. No `tools` field (the agent inherits everything) gives no line.
export function permissionLine(tools, disallowed = []) {
  if (!tools) return null;
  const granted = tools.filter((t) => !disallowed.includes(t));
  if (granted.some((t) => EDIT_TOOLS.includes(t))) return 'Permissions: may edit files within the scope described below.';
  if (granted.includes('Bash')) return 'Permissions: read-only. Run commands only to test or inspect, never to change files.';
  return 'Permissions: read-only. Do not edit files or run commands.';
}

// Instructions text for generated targets: rewritten body, with the permission line first.
function instructionsOf(a) {
  const body = rewriteBody(a.body);
  const perm = permissionLine(a.tools, a.disallowed);
  if (!perm) return body;
  return body.trim() ? `${perm}\n\n${body}` : `${perm}\n`;
}

// Claude tool name -> target tool name. Never maps Agent/Task (no nesting in other tools' lists).
// Gemini names come from google-gemini/gemini-cli packages/core/src/tools/definitions/base-declarations.ts
// (read_file, grep_search, glob, run_shell_command, write_file, replace, web_fetch, google_web_search).
// The research file only shows read_file and grep_search in a doc example; the rest are from that source.
const GEMINI_TOOLS = {
  Read: 'read_file', Grep: 'grep_search', Glob: 'glob', Bash: 'run_shell_command',
  Write: 'write_file', Edit: 'replace', MultiEdit: 'replace', WebFetch: 'web_fetch', WebSearch: 'google_web_search',
};
// Copilot aliases from github/docs custom-agents-configuration: execute, read, edit, search, web, todo.
const COPILOT_TOOLS = {
  Read: 'read', Grep: 'search', Glob: 'search', Bash: 'execute', Edit: 'edit', Write: 'edit',
  MultiEdit: 'edit', NotebookEdit: 'edit', WebFetch: 'web', WebSearch: 'web', TodoWrite: 'todo',
};

// Allowlist in the target's names; null = no `tools` key (agent inherits all tools).
function mapTools(a, table, target, warn) {
  if (!a.tools) return null;
  const out = [...new Set(a.tools.filter((t) => !a.disallowed.includes(t)).map((t) => table[t]).filter(Boolean))];
  if (!out.length) warn(`${target}: none of the tools [${a.tools.join(', ')}] map to ${target} tool names; tools omitted (agent inherits all)`);
  return out.length ? out : null;
}

const tomlBasic = (s) => JSON.stringify(s).replace(/\x7f/g, '\\u007f');

// Multi-line TOML string: literal '''...''' when possible, else escaped """...""" (body has ''' or control chars).
export function tomlMultiline(body) {
  if (!body.includes("'''") && !/[\x00-\x08\x0b-\x1f\x7f]/.test(body)) return `'''\n${body}'''`;
  const esc = body
    .replace(/\\/g, '\\\\')
    .replace(/[\x00-\x08\x0b-\x1f\x7f]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, '0')}`)
    .replace(/"""/g, '""\\"')
    .replace(/"$/, '\\"');
  return `"""\n${esc}"""`;
}

// Codex: name, description, developer_instructions; model keys only when --model-map maps the tier.
// Reasoning effort comes from the Claude `effort` field when it is one of Codex's levels.
const CODEX_EFFORT = ['low', 'medium', 'high', 'xhigh', 'max'];
function renderCodex(a, { rel, mapped, warn }) {
  if (!a.body.trim()) return warn('codex: empty instructions (developer_instructions is required); skipped');
  const lines = [`# ${note(rel)}`, `name = ${tomlBasic(a.name)}`, `description = ${tomlBasic(a.description)}`];
  if (mapped) {
    lines.push(`model = ${tomlBasic(mapped)}`);
    if (CODEX_EFFORT.includes(a.effort)) lines.push(`model_reasoning_effort = ${tomlBasic(a.effort)}`);
  }
  lines.push(`developer_instructions = ${tomlMultiline(instructionsOf(a))}`);
  return lines.join('\n') + '\n';
}

function renderGemini(a, { rel, mapped, warn }) {
  if (!/^[a-z0-9_-]+$/.test(a.name)) return warn(`gemini: name "${a.name}" must be lowercase letters, digits, hyphens or underscores; skipped`);
  const lines = [`name: ${a.name}`, `description: ${JSON.stringify(a.description)}`, `model: ${yamlStr(mapped || 'inherit')}`];
  const tools = mapTools(a, GEMINI_TOOLS, 'gemini', warn);
  if (tools) lines.push('tools:', ...tools.map((t) => `  - ${t}`));
  return mdFile(lines, a, rel);
}

// opencode: permission instead of tools. Agents that cannot edit get edit: deny; bash is denied
// unless Bash is available (read-only agents with Bash get ask). Agents with all tools get no block.
function renderOpencode(a, { rel, mapped, warn }) {
  const lines = [`description: ${JSON.stringify(a.description)}`, 'mode: subagent'];
  if (mapped) {
    if (mapped.includes('/')) lines.push(`model: ${yamlStr(mapped)}`);
    else warn(`opencode: model "${mapped}" has no provider/ prefix; model omitted`);
  }
  const canEdit = (a.tools ? a.tools.some((t) => EDIT_TOOLS.includes(t)) : true) && !(a.disallowed.includes('Edit') && a.disallowed.includes('Write'));
  const canBash = (a.tools ? a.tools.includes('Bash') : true) && !a.disallowed.includes('Bash');
  const perm = [];
  if (!canEdit) perm.push('edit: deny');
  if (!canBash) perm.push('bash: deny');
  else if (!canEdit && a.tools) perm.push('bash: ask');
  if (perm.length) lines.push('permission:', ...perm.map((p) => `  ${p}`));
  return mdFile(lines, a, rel);
}

// Copilot: description is required; name optional. tools only through the verified alias table.
function renderCopilot(a, { rel, mapped, warn }) {
  const lines = [`name: ${yamlStr(a.name)}`, `description: ${JSON.stringify(a.description)}`];
  const tools = mapTools(a, COPILOT_TOOLS, 'copilot', warn);
  if (tools) lines.push(`tools: [${tools.map((t) => JSON.stringify(t)).join(', ')}]`);
  if (mapped) lines.push(`model: ${yamlStr(mapped)}`);
  return mdFile(lines, a, rel);
}

export const TARGETS = {
  codex: { dir: '.codex/agents', ext: '.toml', marker: TOML_MARKER_RE, render: renderCodex },
  gemini: { dir: '.gemini/agents', ext: '.md', marker: MD_MARKER_RE, render: renderGemini },
  opencode: { dir: '.opencode/agents', ext: '.md', marker: MD_MARKER_RE, render: renderOpencode },
  copilot: { dir: '.github/agents', ext: '.agent.md', marker: MD_MARKER_RE, render: renderCopilot },
};

// "fast=X,standard=Y" -> { fast: 'X', standard: 'Y' } or { error }.
export function parseModelMap(s) {
  const map = {};
  for (const pair of s.split(',').map((p) => p.trim()).filter(Boolean)) {
    const at = pair.indexOf('=');
    const tier = pair.slice(0, at).trim();
    const value = pair.slice(at + 1).trim();
    if (at < 1 || !value || !['fast', 'standard', 'deep'].includes(tier)) {
      return { error: `bad --model-map entry "${pair}" (expected fast=, standard= or deep=<model>)` };
    }
    map[tier] = value;
  }
  return { map };
}

// ---------------------------------------------------------------------------
// Sync
// ---------------------------------------------------------------------------

function listAgents(root) {
  const base = path.join(root, AGENTS_DIR);
  const found = [];
  const walk = (relDir) => {
    let entries;
    try {
      entries = fs.readdirSync(path.join(base, relDir), { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of entries.sort((a, b) => (a.name < b.name ? -1 : 1))) {
      const rel = relDir ? `${relDir}/${e.name}` : e.name;
      if (e.isDirectory()) walk(rel);
      else if (e.name.endsWith('.md') && (e.isFile() || e.isSymbolicLink())) found.push(rel);
    }
  };
  walk('');
  return found;
}

function readIfExists(file) {
  try {
    return fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') return null;
    throw err;
  }
}

// First path component of `rel` (under root) that exists but is not a directory, or null.
function blockingFile(root, rel) {
  let cur = root;
  let shown = '';
  for (const part of rel.split('/')) {
    cur = path.join(cur, part);
    shown = shown ? `${shown}/${part}` : part;
    let st;
    try {
      st = fs.lstatSync(cur);
      if (st.isSymbolicLink()) st = fs.statSync(cur);
    } catch {
      return null;
    }
    if (!st.isDirectory()) return shown;
  }
  return null;
}

const toLF = (s) => s.replace(/\r\n/g, '\n');

function staleFiles(dir, ext, marker, keep) {
  let names;
  try {
    names = fs.readdirSync(dir);
  } catch {
    return [];
  }
  return names
    .filter((n) => n.endsWith(ext) && !keep.has(n))
    .filter((n) => marker.test(toLF(readIfExists(path.join(dir, n)) || '')))
    .sort();
}

// Returns { actions: [{ action, target, file }], warnings: string[], conflicts, changes }.
export function syncAgents({ dir = process.cwd(), targets, modelMap = {}, check = false, dryRun = false }) {
  const root = path.resolve(dir);
  const readOnly = check || dryRun;
  const actions = [];
  const warnings = [];
  const record = (action, target, file) => actions.push({ action, target, file });
  const agents = listAgents(root).map((rel) => {
    const stem = path.basename(rel, '.md');
    const agent = parseAgent(fs.readFileSync(path.join(root, AGENTS_DIR, rel), 'utf8'), stem);
    return { rel, file: agent.name.replace(/[^A-Za-z0-9._-]/g, '-'), agent };
  });

  for (const target of targets) {
    const { dir: outDir, ext, marker, render } = TARGETS[target];
    const keep = new Set();
    const warn = (rel) => (msg) => {
      warnings.push(`${AGENTS_DIR}/${rel}: ${msg}`);
      return null;
    };
    const blocker = agents.length ? blockingFile(root, outDir) : null;
    if (blocker) {
      record('conflict', target, `${blocker} is a file, not a directory; left alone`);
      continue;
    }
    for (const { rel, file: stem, agent } of agents) {
      if (!agent.description) {
        warn(rel)(`${target}: no description; skipped (Claude Code skips such agents too)`);
        continue;
      }
      const file = `${outDir}/${stem}${ext}`;
      if (keep.has(`${stem}${ext}`)) {
        record('conflict', target, `${file} (name clash: ${rel} maps to an earlier agent)`);
        continue;
      }
      const output = render(agent, { rel, mapped: modelMap[tierOf(agent.model)], warn: warn(rel) });
      if (output === null) continue;
      keep.add(`${stem}${ext}`);
      const abs = path.join(root, file);
      const raw = readIfExists(abs);
      // CRLF and LF compare equal, so a mirror converted by core.autocrlf stays green.
      const current = raw === null ? null : toLF(raw);
      if (current === null || marker.test(current)) {
        if (current === output) record('unchanged', target, file);
        else {
          record('write', target, file);
          if (!readOnly) {
            fs.mkdirSync(path.dirname(abs), { recursive: true });
            fs.writeFileSync(abs, output); // LF, whatever the source used
          }
        }
      } else {
        record('conflict', target, `${file} (exists without the generated marker; left alone)`);
      }
    }
    for (const n of staleFiles(path.join(root, outDir), ext, marker, keep)) {
      record('remove', target, `${outDir}/${n}`);
      if (!readOnly) fs.rmSync(path.join(root, outDir, n));
    }
  }

  const count = (a) => actions.filter((x) => x.action === a).length;
  return { root, actions, warnings, conflicts: count('conflict'), changes: count('write') + count('remove') };
}

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

function parseArgs(argv) {
  const opts = { dir: process.cwd(), targets: [], modelMap: {}, check: false, dryRun: false };
  const list = (v) => v.split(',').map((t) => t.trim()).filter(Boolean);
  for (let i = 0; i < argv.length; i++) {
    let a = argv[i];
    let v;
    if (a === '--check') opts.check = true;
    else if (a === '--dry-run') opts.dryRun = true;
    else if (a === '-h' || a === '--help') return { help: true };
    else {
      const eq = a.match(/^(--(?:dir|targets|model-map))=(.*)$/s);
      if (eq) [, a, v] = eq;
      else if (['--dir', '--targets', '--model-map'].includes(a)) {
        v = argv[++i];
        if (v === undefined) return { error: `${a} needs a value` };
      } else return { error: `unknown argument: ${argv[i]}` };
      if (a === '--dir') opts.dir = v;
      else if (a === '--targets') opts.targets = list(v);
      else {
        const parsed = parseModelMap(v);
        if (parsed.error) return { error: parsed.error };
        opts.modelMap = parsed.map;
      }
    }
  }
  if (!opts.targets.length) return { error: 'missing --targets' };
  const unknown = opts.targets.filter((t) => !TARGETS[t]);
  if (unknown.length) return { error: `unknown target: ${unknown.join(', ')}` };
  opts.targets = [...new Set(opts.targets)];
  return { opts };
}

// Returns the exit code.
export function run(argv, out = process.stdout, err = process.stderr) {
  const parsed = parseArgs(argv);
  if (parsed.help) {
    out.write(USAGE);
    return 0;
  }
  if (parsed.error) {
    err.write(`sync-agents: ${parsed.error}\n${USAGE}`);
    return 2;
  }
  const { opts } = parsed;
  if (!fs.existsSync(opts.dir) || !fs.statSync(opts.dir).isDirectory()) {
    err.write(`sync-agents: not a directory: ${opts.dir}\n`);
    return 2;
  }
  const result = syncAgents(opts);
  for (const { action, target, file } of result.actions) out.write(`${action.padEnd(9)} ${target.padEnd(8)} ${file}\n`);
  for (const w of result.warnings) err.write(`warn: ${w}\n`);
  const n = (a) => result.actions.filter((x) => x.action === a).length;
  const mode = opts.check ? ' (check: nothing written)' : opts.dryRun ? ' (dry run: nothing written)' : '';
  out.write(`summary: ${n('write')} write, ${n('unchanged')} unchanged, ${n('remove')} remove, ${n('conflict')} conflict${mode}\n`);
  if (result.conflicts) return 1;
  if (opts.check && result.changes) return 1;
  return 0;
}

// True when this file is the process entry point, including via a symlinked path.
function isEntryPoint() {
  if (!process.argv[1]) return false;
  try {
    return fs.realpathSync(process.argv[1]) === fs.realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return false;
  }
}

if (isEntryPoint()) {
  try {
    process.exitCode = run(process.argv.slice(2));
  } catch (e) {
    process.stderr.write(`sync-agents: ${e && e.message ? e.message : e}\n`);
    process.exitCode = 1;
  }
}
